/** True when one of the bundled cuneiform fonts has a real glyph for the code point. */
export function isDrawableCodePoint(cp: number): boolean {
  let lo = 0
  let hi = SPANS.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    const [a, b] = SPANS[mid]!
    if (cp < a) hi = mid - 1
    else if (cp > b) lo = mid + 1
    else return true
  }
  return false
}
